const videoUrl = $json.url;
const videoId = videoUrl.includes('v=') ? videoUrl.split('v=')[1].substring(0, 11) : null;
return {
  videoId: videoId,
  title: $json.title || 'Untitled Video',
  description: $json.description || '',
  channelName: $json.channelName || 'Unknown',
  duration: $json.duration || 'N/A',
  uploadDate: new Date().toISOString()
};

const mockTranscript = `Today we're discussing artificial intelligence and automation. AI is transforming industries. Machine learning and deep learning enable powerful applications. Join us in exploring these technologies.`;
return {
  transcript: mockTranscript,
  chunks: mockTranscript.split('. ').map((c, i) => ({ index: i, text: c.trim() })),
  wordCount: mockTranscript.split(' ').length,
  processingTime: new Date().toISOString()
};

return {
  originalTranscript: $input.first().json.transcript,
  rewrittenContent: $json.choices ? $json.choices[0].message.content : 'Rewritten content',
  contentType: 'video_script',
  seoKeywords: ['AI', 'automation', 'technology'],
  generatedAt: new Date().toISOString()
};

return {
  videoTitle: ($input.first().json.title || 'Video') + ' - AI Rewritten',
  videoDescription: 'Created with AI automation',
  tags: ['AI', 'automation'],
  category: 'Education',
  privacyStatus: 'private',
  voiceoverReady: true
};

return {
  status: 'completed',
  timestamp: new Date().toISOString(),
  message: 'Workflow completed successfully',
  nextSteps: 'Import video file and upload to YouTube'
};
